import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import test from 'node:test';

import {
  boundSource,
  geometryState,
  isResolvedSource,
  mappedPressureValues,
  readSimulation,
  resolveSource,
  STRIVE_INSOLE_LAYOUT,
  SYNTHETIC_INSOLE_LAYOUT,
  SYNTHETIC_LAYOUT_SHA256,
  syntheticLayoutCanonical,
} from '@prostriveorg/ui/dynamic/data';
import type { ResolvedSource } from '@prostriveorg/ui/dynamic/data';

/** Generated by sensor_core's `print_descriptor` test from the real simulator. */
const fixture = JSON.parse(
  readFileSync(new URL('./fixtures/simulation-descriptor.json', import.meta.url), 'utf8'),
) as { descriptor: Record<string, unknown>; status: Record<string, unknown> };
const descriptor = fixture.descriptor;
const clone = () => structuredClone(descriptor) as Record<string, any>;

const source = { id: STRIVE_INSOLE_LAYOUT.id, version: STRIVE_INSOLE_LAYOUT.version };
const channels = Uint16Array.from({ length: 64 }, (_, i) => i * 10);
const mapped = {
  ...STRIVE_INSOLE_LAYOUT,
  channelForPad: Array.from({ length: 64 }, (_, i) => 63 - i),
};

test('unconfirmed geometry never receives values even with a matching layout reference', () => {
  assert.equal(geometryState(STRIVE_INSOLE_LAYOUT, source), 'unmapped');
  assert.equal(mappedPressureValues(STRIVE_INSOLE_LAYOUT, source, channels), null);
  assert.ok(STRIVE_INSOLE_LAYOUT.channelForPad.every((channel) => channel === null));
  // The hardware layout cannot acquire a mapping by mutation.
  assert.throws(() => {
    (STRIVE_INSOLE_LAYOUT.channelForPad as (number | null)[])[0] = 3;
  });
  assert.equal(STRIVE_INSOLE_LAYOUT.channelForPad[0], null);
});

test('a complete mapping cannot reinterpret data with missing or different layout provenance', () => {
  assert.equal(geometryState(mapped), 'unbound');
  assert.equal(mappedPressureValues(mapped, undefined, channels), null);
  assert.equal(
    mappedPressureValues(mapped, { ...source, version: source.version + 1 }, channels),
    null,
  );
  assert.equal(mappedPressureValues(mapped, { ...source, id: 'other-size' }, channels), null);
  assert.equal(geometryState(mapped, source), 'ready');
  const values = mappedPressureValues(mapped, source, channels)!;
  assert.equal(values[0], 630);
  assert.equal(values[63], 0);
  assert.equal(mappedPressureValues(mapped, source, channels.slice(1)), null);
});

test('duplicate or out-of-range channel assignments never colour pads', () => {
  for (const channel of [-1, 64, 1.5, null, 62]) {
    const invalid = { ...mapped, channelForPad: [channel, ...mapped.channelForPad.slice(1)] };
    assert.equal(geometryState(invalid, source), 'unmapped');
    assert.equal(mappedPressureValues(invalid, source, channels), null);
  }
});

test('the library copy of the synthetic layout hashes to the simulator pin', () => {
  const hash = createHash('sha256')
    .update(syntheticLayoutCanonical(SYNTHETIC_INSOLE_LAYOUT))
    .digest('hex');
  assert.equal(hash, SYNTHETIC_LAYOUT_SHA256);
  assert.deepEqual(SYNTHETIC_INSOLE_LAYOUT.pads, STRIVE_INSOLE_LAYOUT.pads);
  assert.equal(new Set(SYNTHETIC_INSOLE_LAYOUT.channelForPad).size, 64);
});

test('only a validated mock-ble descriptor resolves the synthetic layout', () => {
  const resolved = resolveSource({ acquisitionMode: 'mock-ble', simulation: descriptor });
  assert.ok(resolved);
  assert.equal(resolved.layout, SYNTHETIC_INSOLE_LAYOUT);
  assert.equal(geometryState(resolved.layout, resolved.reference), 'ready');
  assert.equal(readSimulation(fixture.status)?.preset, 'running-heel');
  assert.equal(resolveSource({ acquisitionMode: 'mock-ble' }), null);
  assert.equal(resolveSource({ acquisitionMode: 'bluez', simulation: descriptor }), null);
  assert.equal(resolveSource(null), null);
  for (const change of [
    (d: Record<string, any>) => (d.layout.Left.sha256 = '0'.repeat(64)),
    (d: Record<string, any>) => (d.modelVersion = 2),
    (d: Record<string, any>) => (d.imu.placement.Right = ['ankle', 'toe']),
  ]) {
    const d = clone();
    change(d);
    assert.equal(resolveSource({ acquisitionMode: 'mock-ble', simulation: d }), null);
  }
});

test('a hand-built or cast source binding is never honoured', () => {
  const resolved = resolveSource({ acquisitionMode: 'mock-ble', simulation: descriptor })!;
  assert.equal(isResolvedSource(resolved), true);
  assert.equal(boundSource(resolved), resolved);
  assert.ok(Object.isFrozen(resolved));
  // Real hardware data dressed up with the synthetic layout, e.g. via a cast or spread.
  const forged = {
    layout: SYNTHETIC_INSOLE_LAYOUT,
    reference: { id: SYNTHETIC_INSOLE_LAYOUT.id, version: SYNTHETIC_INSOLE_LAYOUT.version },
    simulation: resolved.simulation,
  } as ResolvedSource;
  assert.equal(isResolvedSource(forged), false);
  assert.equal(boundSource(forged), null);
  assert.equal(boundSource({ ...resolved }), null);
  assert.equal(boundSource(null), null);
  assert.equal(isResolvedSource(JSON.parse(JSON.stringify(resolved))), false);
});
